CREATE TABLE orders (id BIGSERIAL PRIMARY KEY, order_code TEXT NOT NULL UNIQUE, team_id BIGINT NOT NULL REFERENCES teams(id), stock_id BIGINT NOT NULL REFERENCES stocks(id), side TEXT NOT NULL, quantity INTEGER NOT NULL, price NUMERIC(14,2) NOT NULL, trade_value NUMERIC(16,2) NOT NULL, brokerage NUMERIC(16,2) NOT NULL, status TEXT NOT NULL DEFAULT 'EXCHANGE_PENDING', created_at TIMESTAMP NOT NULL DEFAULT now())